#!/usr/bin/env python3
"""
cron_deadline_check.py — Claw Connector proactive deadline alerts (Path A)

Registered by `negotiate.py install` to run every 15 minutes via crontab:
  */15 * * * * python3 {skill_dir}/cron_deadline_check.py >> {skill_dir}/cron.log 2>&1

What it does:
  1. Reads MEMORY.md for all [ACTIVE] commitments
  2. For any commitment whose deadline is within 2 hours: writes a plain-language
     alert to skills/claw-bond/cron_alerts.json
  3. Attempts `openclaw notify "<message>"` — if OpenClaw CLI is in PATH, this
     delivers a real message through the human's active channel (WhatsApp, Telegram,
     etc.) without them needing to open their agent
  4. Falls back gracefully if the CLI is unavailable

Path B fallback: diplomat-heartbeat hook reads cron_alerts.json on every human
message and surfaces any unshown alerts, even without cron.

Security: reads workspace files only, no network calls, no subprocess execution
except `openclaw notify` (which is the declared delivery channel).
"""

from __future__ import annotations

import datetime
import json
import os
import re
import subprocess
import sys
import tempfile
import uuid

# ─── Workspace detection ──────────────────────────────────────────────────────
def get_workspace_root() -> str:
    root = os.environ.get("DIPLOMAT_WORKSPACE", "")
    if not root:
        # Default OpenClaw workspace path
        root = os.path.expanduser("~/.openclaw/workspace")
    if not os.path.isdir(root):
        # Try cwd as fallback
        root = os.getcwd()
    return root


def get_skill_dir(workspace_root: str) -> str:
    return os.path.join(workspace_root, "skills", "claw-bond")


# ─── MEMORY.md parser ─────────────────────────────────────────────────────────
_ACTIVE_ENTRY_RE = re.compile(
    r"\[ACTIVE\].*?Peer:\s*(?P<peer>[^|]+)\|.*?My:\s*(?P<my>[^|]+)\|.*?"
    r"Due:\s*(?P<due>[^|]+)\|.*?ID:\s*`?(?P<id>[^`\s]+)`?",
    re.IGNORECASE,
)

def parse_active_entries(memory_md: str) -> list[dict]:
    """Extract [ACTIVE] commitment entries from MEMORY.md."""
    entries = []
    in_section = False
    for line in memory_md.splitlines():
        if "## Diplomat Commitments" in line:
            in_section = True
            continue
        if in_section and line.startswith("## "):
            break
        if in_section and "[ACTIVE]" in line.upper():
            m = _ACTIVE_ENTRY_RE.search(line)
            if m:
                entries.append({
                    "peer":  m.group("peer").strip(),
                    "my":    m.group("my").strip(),
                    "due":   m.group("due").strip(),
                    "id":    m.group("id").strip(),
                })
    return entries


def parse_due(raw: str) -> datetime.datetime | None:
    """Parse 'YYYY-MM-DD HH:MM UTC' or ISO8601 into a UTC datetime."""
    raw = raw.strip()
    for fmt in ("%Y-%m-%d %H:%M UTC", "%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S"):
        try:
            dt = datetime.datetime.strptime(raw, fmt)
            return dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
    # Try normalising space→T and stripping UTC
    try:
        normalised = raw.replace(" UTC", "Z").replace(" ", "T")
        return datetime.datetime.fromisoformat(normalised.replace("Z", "+00:00"))
    except ValueError:
        return None


# ─── cron_alerts.json writer ──────────────────────────────────────────────────
def load_alerts(alerts_path: str) -> dict:
    try:
        with open(alerts_path) as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {"alerts": []}


def save_alerts(alerts_path: str, data: dict) -> None:
    tmp_fd, tmp_path = tempfile.mkstemp(dir=os.path.dirname(alerts_path), suffix=".tmp")
    try:
        with os.fdopen(tmp_fd, "w") as f:
            json.dump(data, f, indent=2)
        os.replace(tmp_path, alerts_path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def alert_already_written(existing_alerts: list, commitment_id: str) -> bool:
    """Avoid writing duplicate alerts for the same commitment in the same window."""
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(hours=3)
    for a in existing_alerts:
        if a.get("commitment_id") == commitment_id:
            try:
                written_at = datetime.datetime.fromisoformat(a["created_at"])
                if written_at > cutoff:
                    return True
            except (KeyError, ValueError):
                continue
    return False


# ─── OpenClaw notify attempt ─────────────────────────────────────────────────
def try_openclaw_notify(message: str) -> bool:
    """
    Attempt to deliver a proactive message through OpenClaw's active messaging
    channel (WhatsApp, Telegram, etc.) via the `openclaw notify` CLI.
    Returns True if the notification was delivered, False if unavailable.
    This is a best-effort call — failure is non-fatal.
    """
    try:
        result = subprocess.run(
            ["openclaw", "notify", message],
            capture_output=True, text=True, timeout=10,
        )
        return result.returncode == 0
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return False


# ─── Main ─────────────────────────────────────────────────────────────────────
def main() -> None:
    workspace_root = get_workspace_root()
    skill_dir      = get_skill_dir(workspace_root)
    memory_path    = os.path.join(workspace_root, "MEMORY.md")
    alerts_path    = os.path.join(skill_dir, "cron_alerts.json")

    # Read MEMORY.md
    try:
        with open(memory_path) as f:
            memory_md = f.read()
    except FileNotFoundError:
        # No commitments yet — nothing to check
        print("[cron_deadline_check] MEMORY.md not found — nothing to check.")
        return

    entries = parse_active_entries(memory_md)
    if not entries:
        print("[cron_deadline_check] No active commitments found.")
        return

    now        = datetime.datetime.now(datetime.timezone.utc)
    alert_data = load_alerts(alerts_path)
    new_alerts = 0

    for entry in entries:
        deadline = parse_due(entry["due"])
        if deadline is None:
            print(f"[cron_deadline_check] Could not parse deadline for {entry['id']}: {entry['due']}")
            continue

        time_left = deadline - now
        hours_left = time_left.total_seconds() / 3600

        # Alert window: deadline is within 2 hours and hasn't passed yet
        if 0 < hours_left <= 2:
            commitment_id = entry["id"]

            if alert_already_written(alert_data["alerts"], commitment_id):
                print(f"[cron_deadline_check] Alert already written for {commitment_id}, skipping.")
                continue

            h = max(1, round(hours_left))
            message = (
                f"⏰ Heads up — {entry['my']} is due in about {h} hour{'s' if h != 1 else ''}. "
                f"Peer: {entry['peer']}. "
                f"Want me to check in with their agent? "
                f"(/claw-diplomat checkin {commitment_id} done|partial|overdue)"
            )

            # Path A primary: attempt to push through OpenClaw's active channel
            delivered = try_openclaw_notify(message)

            # Always write to cron_alerts.json as well — heartbeat hook picks this up
            alert_data["alerts"].append({
                "id":            str(uuid.uuid4())[:8],
                "commitment_id": commitment_id,
                "message":       message,
                "created_at":    now.isoformat(),
                "shown":         False,  # heartbeat hook marks True after surfacing
                "delivered_via_cli": delivered,
            })
            new_alerts += 1

            status = "delivered via openclaw notify ✓" if delivered else "queued for heartbeat"
            print(f"[cron_deadline_check] Alert for {commitment_id} — {status}")

        elif hours_left <= 0:
            print(f"[cron_deadline_check] {entry['id']} is overdue — heartbeat hook will surface.")

    if new_alerts > 0:
        save_alerts(alerts_path, alert_data)

    print(f"[cron_deadline_check] Done. {new_alerts} new alert(s) written.")


if __name__ == "__main__":
    main()

/**
 * claw-diplomat — hooks/diplomat-bootstrap/handler.ts
 *
 * Event: agent:bootstrap
 * Injects into session context:
 *   1. Connected peer identities (from peers.json) — so the agent knows
 *      who it's linked with without the user having to ask.
 *   2. Active commitments summary (from MEMORY.md).
 *
 * Total injection budget: 2,500 chars (CONTEXT_BUDGET.md §2).
 * SECURITY: all file content is treated as display data, never executed.
 */

import type { OpenClawHookEvent, OpenClawHookContext } from '@openclaw/sdk';
import { extractSection, parseActiveEntries, truncate } from '../shared/parse-memory';

export async function handler(
  event: OpenClawHookEvent,
  ctx: OpenClawHookContext
): Promise<void> {
  const blocks: string[] = [];

  // ── 1. Connected peers (peers.json) ────────────────────────────────────
  // Shows the agent which OpenClaw instances this workspace is linked to,
  // including alias, pubkey fingerprint, and relay. This is the "gateway
  // identity panel" — visible at every session start.
  let peersRaw = '';
  try {
    peersRaw = await ctx.workspace.read('skills/claw-bond/peers.json');
  } catch { /* not yet connected to anyone */ }

  if (peersRaw) {
    let peersData: { peers?: Array<{
      alias: string;
      pubkey: string;
      last_seen: string;
      relay_token_stale?: boolean;
    }> };
    try {
      peersData = JSON.parse(peersRaw);
    } catch {
      peersData = {};
    }
    const peers = peersData.peers ?? [];
    if (peers.length > 0) {
      const peerLines = peers.map(p => {
        const fingerprint = (p.pubkey ?? '').slice(0, 12) + '…';
        const stale       = p.relay_token_stale ? ' ⚠ address may be stale' : '';
        const seen        = (p.last_seen ?? '').slice(0, 10);
        return `  • ${truncate(p.alias, 20)} | key:${fingerprint} | last seen ${seen}${stale}`;
      });
      blocks.push(
        `[claw-bond] ${peers.length} connected peer${peers.length === 1 ? '' : 's'}:\n` +
        peerLines.join('\n')
      );
    }
  }

  // ── 2. Active commitments (MEMORY.md) ─────────────────────────────────
  let memory = '';
  try {
    memory = await ctx.workspace.read('MEMORY.md');
  } catch { /* MEMORY.md may not exist on fresh install */ }

  if (memory) {
    const section = extractSection(memory, '## Diplomat Commitments');
    if (section) {
      const active = parseActiveEntries(section);
      if (active.length > 0) {
        const n     = active.length;
        const lines = active.map(e =>
          `  • ${truncate(e.peer, 20)} | ${truncate(e.myTask, 40)} due ${e.deadlineLocal} → [ACTIVE] (ID: ${e.id})`
        );
        blocks.push(
          `[claw-bond] ${n} active commitment${n === 1 ? '' : 's'}:\n` +
          lines.join('\n')
        );
      }
    }
  }

  if (blocks.length === 0) return;

  // ── Combine blocks and enforce 2,500-char budget ──────────────────────
  const combined = blocks.join('\n\n');
  const capped   = combined.length > 2500 ? combined.slice(0, 2497) + '…' : combined;

  ctx.session.inject(capped);
  ctx.log('DEBUG', `claw-bond bootstrap: injected peer identity + commitment context (${capped.length} chars)`);
}

/**
 * claw-diplomat — hooks/diplomat-gateway/handler.ts
 *
 * Event: gateway:startup
 *
 * Checks whether the inbound relay listener is already running (via PID file).
 * If it is running  → logs and returns silently.
 * If it is not running → writes a flag file and injects a one-line startup
 *   instruction into the agent session so the agent can start listener.py
 *   as a background process on the next /claw-diplomat command.
 *
 * The process launch itself is delegated to the agent (via SKILL.md instructions)
 * rather than being executed here. This keeps the hook layer free of shell
 * execution and uses only the declared workspace filesystem APIs.
 *
 * fail_open: true — if the listener isn't running the user gets a nudge;
 * this is not a hard failure that should block the gateway.
 */

import type { OpenClawHookEvent, OpenClawHookContext } from '@openclaw/sdk';
import * as path from 'path';
import * as fs from 'fs';

export async function handler(
  event: OpenClawHookEvent,
  ctx: OpenClawHookContext
): Promise<void> {
  const workspaceRoot = process.env.DIPLOMAT_WORKSPACE ?? process.cwd();
  const skillDir      = path.join(workspaceRoot, 'skills', 'claw-bond');
  const listenerPath  = path.join(skillDir, 'listener.py');
  const pidPath       = path.join(skillDir, 'listener.pid');
  const flagPath      = path.join(skillDir, 'listener.start_requested');

  // ── Verify the skill is installed ──────────────────────────────────────
  if (!fs.existsSync(listenerPath)) {
    ctx.session.notify(
      '⚠️ claw-bond: listener.py not found — skill may not be installed correctly.\n' +
      'Run: clawhub install claw-bond'
    );
    return;
  }

  // ── Check if listener is already running via PID file ──────────────────
  if (fs.existsSync(pidPath)) {
    const rawPid      = fs.readFileSync(pidPath, 'utf-8').trim();
    const existingPid = parseInt(rawPid, 10);
    if (!isNaN(existingPid)) {
      try {
        // Signal 0 = existence check only — does NOT kill or interact with the process.
        process.kill(existingPid, 0);
        ctx.log('INFO', `claw-bond listener is running (PID ${existingPid})`);
        return; // Already running — nothing to do
      } catch {
        // Process is gone — PID file is stale; clean it up and fall through
        ctx.log('DEBUG', `claw-bond stale PID ${existingPid} — will request restart`);
        try { fs.unlinkSync(pidPath); } catch { /* ignore */ }
      }
    }
  }

  // ── Listener is not running ─────────────────────────────────────────────
  // Write a flag file so the agent (and any tooling) can detect this state.
  // The agent reads SKILL.md which instructs it to run listener.py in the
  // background when it sees this flag or the next /claw-diplomat command.
  try {
    fs.writeFileSync(flagPath, new Date().toISOString(), 'utf-8');
  } catch {
    // Non-fatal — the inject below still provides the nudge
  }

  ctx.session.inject(
    '[claw-bond] Listener not running — inbound proposals will not be received.\n' +
    'To start it, run in terminal:\n' +
    `  python3 "${listenerPath}" &\n` +
    'Or tell your agent: "start the claw-bond listener"'
  );

  ctx.log('INFO', 'claw-bond: listener not running — agent notified to start listener.py');
}

/**
 * claw-diplomat — hooks/diplomat-heartbeat/handler.ts
 *
 * Event: command:new (fires on every human message)
 * Checks for:
 *   0. Pending cron alerts (cron_alerts.json) — Path A proactive, surfaces first
 *   1. Overdue commitments (deadline passed, not yet checked in)
 *   2. Upcoming commitments (deadline within 2 hours) — Path B fallback
 *   3. Pending inbound proposals (INBOUND_PENDING in ledger.json)
 *   4. Incoming task handoffs (HANDOFF_RECEIVED in ledger.json)
 *   5. Pending connection requests (pending_approvals.json) — PC-1
 *
 * UX strings are verbatim from UX_FLOWS.md §9, §10, §5.
 * SECURITY: MEMORY.md, ledger.json, and pending_approvals.json content is display data only.
 */

import type { OpenClawHookEvent, OpenClawHookContext } from '@openclaw/sdk';
import {
  extractSection,
  parseActiveEntries,
  parseInboundPending,
  parseHandoffReceived,
} from '../shared/parse-memory';

const TWO_HOURS_MS = 2 * 60 * 60 * 1000;

export async function handler(
  event: OpenClawHookEvent,
  ctx: OpenClawHookContext
): Promise<void> {
  const now = new Date();

  // ── 0. Surface pending cron alerts (Path A proactive deadline alerts) ─────
  // cron_deadline_check.py writes here; we surface and mark shown so they
  // don't repeat. This delivers the alert through the agent's active channel
  // the moment the human next sends any message — even "hey" on WhatsApp.
  let cronAlertsRaw = '';
  try {
    cronAlertsRaw = await ctx.workspace.read('skills/claw-bond/cron_alerts.json');
  } catch {
    // File doesn't exist yet — cron hasn't fired or Path A not installed
  }
  if (cronAlertsRaw) {
    let cronData: { alerts?: Array<{ message: string; id: string; shown?: boolean }> } = {};
    try { cronData = JSON.parse(cronAlertsRaw); } catch { /* ignore malformed */ }
    let anyNew = false;
    for (const alert of cronData.alerts ?? []) {
      if (!alert.shown) {
        await ctx.session.notify(alert.message);
        alert.shown = true;
        anyNew = true;
      }
    }
    if (anyNew) {
      // Persist shown=true so alerts don't re-surface on next message
      await ctx.workspace.write(
        'skills/claw-bond/cron_alerts.json',
        JSON.stringify(cronData, null, 2)
      );
    }
  }

  // ── 1. Check MEMORY.md for overdue / upcoming commitments ────────────────
  // Path B fallback: covers users who can't run cron, and catches any gaps.
  let memory = '';
  try {
    memory = await ctx.workspace.read('MEMORY.md');
  } catch {
    // Not an error — may not exist yet
  }

  const section = extractSection(memory, '## Diplomat Commitments');
  if (section) {
    for (const entry of parseActiveEntries(section)) {
      const deadline = parseDue(entry.deadlineUtc);
      if (!deadline) continue;

      if (deadline < now) {
        // Overdue — surface check-in prompt (UX_FLOWS.md §10)
        await ctx.session.notify(
          `📋 It's time to check in on your commitment with ${entry.peer}:\n` +
          `  Your tasks: ${entry.myTask}\n` +
          `  Was due: ${entry.deadlineLocal}\n\n` +
          `How did it go?\n` +
          `  /claw-diplomat checkin ${entry.id} done\n` +
          `  /claw-diplomat checkin ${entry.id} partial\n` +
          `  /claw-diplomat checkin ${entry.id} overdue`
        );
      } else if (deadline.getTime() - now.getTime() < TWO_HOURS_MS) {
        // Upcoming — brief reminder (UX_FLOWS.md §9)
        const msLeft   = deadline.getTime() - now.getTime();
        const hoursLeft = Math.max(1, Math.round(msLeft / 3_600_000));
        await ctx.session.notify(
          `⏰ Heads up — you have a commitment due soon:\n` +
          `  With ${entry.peer}: ${entry.myTask}\n` +
          `  Due: ${entry.deadlineLocal} (in about ${hoursLeft} hour${hoursLeft === 1 ? '' : 's'})\n\n` +
          `When you're done: /claw-diplomat checkin ${entry.id} done`
        );
      }
    }
  }

  // ── 2. Check ledger.json for pending inbound proposals ───────────────────
  let ledgerContent = '';
  try {
    ledgerContent = await ctx.workspace.read('skills/claw-bond/ledger.json');
  } catch {
    // ledger.json may not exist yet
  }

  if (ledgerContent) {
    for (const session of parseInboundPending(ledgerContent)) {
      const terms = session.pending_terms;
      const peerAlias = session.peer_alias ?? 'An unknown agent';
      const shortId   = session.session_id?.slice(0, 4) ?? '????';
      const trusted   = terms?.trusted ?? false;

      if (!trusted) {
        // Unknown peer — show quarantine notice (UX_FLOWS.md §5 unknown peer variant)
        const theyDo = terms?.my_tasks?.[0]  ?? '(tasks not shown until authorized)';
        const youDo  = terms?.your_tasks?.[0] ?? '(tasks not shown until authorized)';
        const dl     = terms?.deadline ?? 'unknown';
        await ctx.session.notify(
          `📨 An agent you haven't connected with before wants to negotiate.\n\n` +
          `  Agent key: ${session.peer_alias?.slice(0, 8) ?? '?'}… (from ${terms?.peer_ip ?? 'unknown'})\n\n` +
          `  They're proposing:\n` +
          `  They'll do: ${theyDo}\n` +
          `  You'll do: ${youDo}\n` +
          `  Deadline: ${dl}\n\n` +
          `Do you want to accept this peer and consider their proposal?\n` +
          `  Run: /claw-diplomat peers  to manage connections\n` +
          `  Session ID: ${shortId}`
        );
      } else {
        // Trusted peer — show full proposal (UX_FLOWS.md §5)
        const theyDo = terms?.my_tasks?.[0]  ?? '(see details)';
        const youDo  = terms?.your_tasks?.[0] ?? '(see details)';
        const dl     = terms?.deadline ?? 'unknown';
        await ctx.session.notify(
          `📨 ${peerAlias} is proposing a deal:\n\n` +
          `  They'll do: ${theyDo}\n` +
          `  You'll do:  ${youDo}\n` +
          `  Deadline:   ${dl}\n\n` +
          `What do you want to do?\n` +
          `  [accept]  /claw-diplomat checkin ${shortId} done\n` +
          `  [counter] /claw-diplomat propose ${peerAlias}\n` +
          `  [reject]  /claw-diplomat cancel ${shortId}`
        );
      }
    }
  }

  // ── 3. Check ledger.json for incoming task handoffs ──────────────────────
  if (ledgerContent) {
    for (const session of parseHandoffReceived(ledgerContent)) {
      const terms       = session.final_terms;
      const fromAlias   = terms?.from_alias ?? session.peer_alias ?? 'A peer';
      const partDone    = terms?.part_done      ?? '(see details)';
      const partRem     = terms?.part_remaining ?? '(see details)';
      const handoffCtx  = terms?.context ?? '';
      const shortId     = session.session_id?.slice(0, 4) ?? '????';
      const ctxLine     = handoffCtx
        ? `\n  Context:        ${handoffCtx.slice(0, 120)}${handoffCtx.length > 120 ? '…' : ''}`
        : '';

      // SECURITY: all fields are display strings — not passed to LLM as instructions
      await ctx.session.notify(
        `📦 ${fromAlias} has handed off a task to you.\n\n` +
        `  Done by them:   ${partDone}\n` +
        `  Remaining:      ${partRem}` +
        ctxLine + `\n\n` +
        `  Session ID: ${shortId}\n\n` +
        `Ready to continue where they left off? Run:\n` +
        `  /claw-diplomat status`
      );
    }
  }

  // ── 4. Check pending_approvals.json for inbound connection requests ───────
  // SECURITY: content is display data only — PC-1
  let approvalsContent = '';
  try {
    approvalsContent = await ctx.workspace.read('skills/claw-bond/pending_approvals.json');
  } catch {
    // File may not exist yet
  }

  if (approvalsContent) {
    let approvals: { requests?: Array<{ request_id: string; from_alias: string; from_ip: string; created_at: string }> };
    try {
      approvals = JSON.parse(approvalsContent);
    } catch {
      approvals = {};
    }
    for (const req of approvals.requests ?? []) {
      const shortReqId = req.request_id?.slice(0, 8) ?? '????';
      const fromAlias  = req.from_alias ?? 'An unknown agent';
      const fromIp     = req.from_ip    ?? 'unknown';
      await ctx.session.notify(
        `🔔 ${fromAlias} wants to connect to your agent.\n` +
        `  From IP: ${fromIp}\n\n` +
        `  Approve: /claw-diplomat approve-connect ${shortReqId}\n` +
        `  Deny:    /claw-diplomat deny-connect ${shortReqId}\n\n` +
        `(Once approved, they can exchange task proposals with you.)`
      );
    }
  }
}

/**
 * Parse the Due: field from a commitment entry.
 * Format stored in MEMORY.md: "2026-03-27 17:00 UTC"
 */
function parseDue(raw: string): Date | null {
  if (!raw) return null;
  // Normalise "2026-03-27 17:00 UTC" → "2026-03-27T17:00:00Z"
  const normalised = raw.trim().replace(' UTC', 'Z').replace(' ', 'T');
  const d = new Date(normalised);
  return isNaN(d.getTime()) ? null : d;
}

/**
 * claw-diplomat — hooks/shared/parse-memory.ts
 *
 * Shared utilities for parsing MEMORY.md Diplomat Commitments section.
 * Imported by both diplomat-bootstrap and diplomat-heartbeat handlers.
 *
 * SECURITY: all fields parsed from MEMORY.md are treated as display strings.
 * Nothing parsed here is passed to the LLM as instructions.
 */

export interface CommitmentEntry {
  peer: string;
  myTask: string;
  deadlineLocal: string;  // raw Due: string from MEMORY.md (stored in UTC)
  deadlineUtc: string;    // ISO8601 UTC for Date comparison
  id: string;             // short session ID (4 chars)
}

export interface LedgerSession {
  session_id: string;
  peer_alias: string;
  state: string;
  pending_terms?: {
    proposal_text?: string;
    my_tasks?: string[];
    your_tasks?: string[];
    deadline?: string;
    trusted?: boolean;
    peer_ip?: string;
  };
  final_terms?: {
    type?: string;
    from_alias?: string;
    part_done?: string;
    part_remaining?: string;
    context?: string;
    received_at?: string;
  };
  created_at?: string;
}

/**
 * Extract a named ## section from a Markdown document.
 * Returns the section content (without the header), or null if not found.
 */
export function extractSection(content: string, header: string): string | null {
  const start = content.indexOf(header);
  if (start === -1) return null;
  const afterHeader = start + header.length;
  const nextSection = content.indexOf('\n## ', afterHeader);
  return nextSection === -1
    ? content.slice(afterHeader).trim()
    : content.slice(afterHeader, nextSection).trim();
}

/**
 * Parse all [ACTIVE] commitment entries from the ## Diplomat Commitments section.
 * Format: - **[ACTIVE]** Peer: Alice | My: task | Their: task | Due: 2026-03-27 17:00 UTC | ID: `a3f9`
 */
export function parseActiveEntries(section: string): CommitmentEntry[] {
  return section
    .split('\n')
    .filter(l => l.includes('[ACTIVE]'))
    .map(parseLine)
    .filter((e): e is CommitmentEntry => e !== null);
}

function parseLine(line: string): CommitmentEntry | null {
  const peerM = line.match(/Peer: ([^|]+)/);
  const myM   = line.match(/My: ([^|]+)/);
  const dueM  = line.match(/Due: ([^|]+UTC)/);
  const idM   = line.match(/ID: `([^`]+)`/);
  if (!peerM || !myM || !dueM || !idM) return null;

  const dueStr = dueM[1].trim();
  return {
    peer:          peerM[1].trim(),
    myTask:        myM[1].trim(),
    deadlineLocal: dueStr,
    deadlineUtc:   dueStr, // Due field stored in UTC ISO8601-ish
    id:            idM[1].trim(),
  };
}

/**
 * Truncate a string to max characters, appending '…' if truncated.
 */
export function truncate(s: string, max: number): string {
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}

/**
 * Parse ledger.json and return sessions in INBOUND_PENDING state.
 * Used by diplomat-heartbeat to surface pending inbound proposals.
 */
export function parseInboundPending(ledgerContent: string): LedgerSession[] {
  try {
    const ledger = JSON.parse(ledgerContent) as { sessions?: LedgerSession[] };
    return (ledger.sessions ?? []).filter(s => s.state === 'INBOUND_PENDING');
  } catch {
    return [];
  }
}

/**
 * Parse ledger.json and return sessions in HANDOFF_RECEIVED state.
 * Used by diplomat-heartbeat to surface incoming task handoffs from peers.
 * Each returned session has final_terms with part_done, part_remaining, context.
 */
export function parseHandoffReceived(ledgerContent: string): LedgerSession[] {
  try {
    const ledger = JSON.parse(ledgerContent) as { sessions?: LedgerSession[] };
    return (ledger.sessions ?? []).filter(s => s.state === 'HANDOFF_RECEIVED');
  } catch {
    return [];
  }
}
